import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        long[] score = new long[N];
        for (int i = 0; i < M; i++) {
            int a = fs.nextInt();   // winner of question i
            long s = fs.nextLong(); // score of question i
            score[a - 1] += s;
        }

        long max1 = Long.MIN_VALUE, max2 = Long.MIN_VALUE;
        int cntMax1 = 0;

        for (long x : score) {
            if (x > max1) {
                max2 = max1;
                max1 = x;
                cntMax1 = 1;
            } else if (x == max1) {
                cntMax1++;
            } else if (x > max2) {
                max2 = x;
            }
        }

        long answer = 0;
        for (int i = 0; i < N; i++) {
            long bestOther;
            if (score[i] == max1) {
                if (cntMax1 >= 2) bestOther = max1;
                else bestOther = max2;
            } else {
                bestOther = max1;
            }
            answer = Math.max(answer, bestOther - score[i] + 1);
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

