    long long min_required = 0;

    for (int i = 0; i < N; i++) {
        // Find max score among all other contestants
        long long max_other = 0;
        for (int j = 0; j < N; j++) {
            if (j != i) {
                max_other = max(max_other, scores[j]);
            }
        }

        // We need: scores[i] + S > max_other
        // So: S > max_other - scores[i]
        // Minimum integer S satisfying this: max_other - scores[i] + 1
        long long needed = max_other - scores[i] + 1;
        if (needed > 0) {
            min_required = max(min_required, needed);
        }
    }

