#include <stdio.h>

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    int scores[N];
    for (int i = 0; i < N; i++) {
        scanf("%d", &scores[i]);
    }

    // Find the maximum score after M questions
    int max_score = scores[0];
    for (int i = 1; i < N; i++) {
        if (scores[i] > max_score) {
            max_score = scores[i];
        }
    }

    // Determine the minimum score for the last question
    // For each contestant, we need: scores[i] + S >= max_score (if they are not already max)
    // or scores[i] + S > max_score (if they are tied with max)
    // The condition for a contestant to have a chance is:
    // scores[i] + S > max_score if there are other contestants with max_score
    // scores[i] + S >= max_score if they are the only one with max_score
    // Actually, to ensure any contestant can win, we need each contestant to be able to become
    // strictly greater than all others after adding S.
    // So for each contestant i, we need: scores[i] + S > max_score_for_others
    // where max_score_for_others is the maximum among all contestants except i.
    // But simpler: the condition for contestant i to possibly win is that
    // scores[i] + S > max_score, unless they are already the sole leader.
    // However, if multiple have max_score, then for any of them to win, S must be > 0
    // to break the tie. For others, S must be > max_score - scores[i].

    // The minimum S that works for all contestants is:
    // If there is exactly one contestant with max_score, then that contestant can win with S >= 0
    // (they already win if no one else can surpass them). But we need every contestant to have a chance.
    // For the leader(s), they need S > 0 if there are ties, otherwise S >= 0 suffices.
    // For others, they need S > max_score - scores[i].
    // So overall: S must be at least max(1, max_{i: scores[i] < max_score} (max_score - scores[i] + 1))
    // But if there is a tie for max, then for those tied, S must be at least 1.

    int min_S = 0;
    int leader_count = 0;
    for (int i = 0; i < N; i++) {
        if (scores[i] == max_score) {
            leader_count++;
        }
    }

    // For non-leaders
    for (int i = 0; i < N; i++) {
        if (scores[i] < max_score) {
            int needed = max_score - scores[i] + 1;
            if (needed > min_S) {
                min_S = needed;
            }
        }
    }

    // For leaders, if there is more than one, they need at least 1 to break tie
    if (leader_count > 1 && min_S < 1) {
        min_S = 1;
    }

    printf("%d\n", min_S);

    return 0;
}

