#include <stdio.h>
#include <stdlib.h>

int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    long long *score = (long long *)calloc(N, sizeof(long long));
    if (!score) return 0;

    for (int i = 0; i < M; i++) {
        int a;
        long long s;
        scanf("%d %lld", &a, &s);
        score[a - 1] += s;
    }

    qsort(score, N, sizeof(long long), cmp_ll);

    long long ans;
    if (N == 1) {
        ans = 0;
    } else {
        long long minScore = score[0];
        long long maxScore = score[N - 1];
        ans = maxScore - minScore + 1;
    }

    printf("%lld\n", ans);

    free(score);
    return 0;
}

